# Terraform Module: Bucket + RDS + IAM

I'll provide a complete, modular Terraform implementation supporting dev/prod environments via `.tfvars` files.

## Directory Structure

```
terraform/
├── main.tf
├── variables.tf
├── outputs.tf
├── terraform.tfvars
├── terraform-dev.tfvars
├── terraform-prod.tfvars
└── modules/
    ├── s3/
    │   ├── main.tf
    │   ├── variables.tf
    │   └── outputs.tf
    ├── rds/
    │   ├── main.tf
    │   ├── variables.tf
    │   └── outputs.tf
    └── iam/
        ├── main.tf
        ├── variables.tf
        └── outputs.tf
```

## Root Module

### `main.tf`

```hcl
terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
  # Uncomment for remote state (S3 + DynamoDB locking)
  # backend "s3" {
  #   bucket         = "terraform-state-bucket"
  #   key            = "infrastructure/terraform.tfstate"
  #   region         = "us-east-1"
  #   dynamodb_table = "terraform-locks"
  #   encrypt        = true
  # }
}

provider "aws" {
  region = var.aws_region

  default_tags {
    tags = {
      Environment = var.environment
      ManagedBy   = "Terraform"
      Project     = var.project_name
    }
  }
}

# S3 Module
module "s3" {
  source = "./modules/s3"

  bucket_name              = "${var.project_name}-assets-${var.environment}"
  environment              = var.environment
  enable_versioning        = true
  enable_encryption        = true
  encryption_key_arn       = var.kms_key_arn
  block_public_access      = true
  enable_replication       = var.environment == "prod" ? true : false
  replication_region       = var.replication_region
  replication_bucket_arn   = var.replication_bucket_arn
  lifecycle_retention_days = var.s3_retention_days
}

# RDS Module
module "rds" {
  source = "./modules/rds"

  identifier             = "${var.project_name}-db-${var.environment}"
  engine                 = "postgres"
  engine_version         = var.rds_engine_version
  instance_class         = var.rds_instance_class
  allocated_storage      = var.rds_allocated_storage
  storage_encrypted      = true
  kms_key_id             = var.kms_key_arn
  db_name                = var.db_name
  username               = var.db_username
  password               = var.db_password # Use var or random_password
  deletion_protection    = var.environment == "prod" ? true : false
  backup_retention_days  = var.rds_backup_retention
  multi_az               = var.environment == "prod" ? true : false
  publicly_accessible    = false
  db_subnet_group_name   = var.db_subnet_group_name
  vpc_security_group_ids = var.db_security_group_ids
  skip_final_snapshot    = var.environment == "prod" ? false : true
  final_snapshot_id      = var.environment == "prod" ? "${var.project_name}-db-final-snapshot-${formatdate("YYYY-MM-DD-hhmm", timestamp())}" : null

  depends_on = [module.iam]
}

# IAM Module
module "iam" {
  source = "./modules/iam"

  service_account_name = "${var.project_name}-sa-${var.environment}"
  environment          = var.environment
  s3_bucket_arn        = module.s3.bucket_arn
  s3_bucket_name       = module.s3.bucket_name
  rds_resource_id      = module.rds.db_resource_id
  rds_arn              = module.rds.db_arn
  enable_oidc_trust    = var.environment == "prod" ? true : false
  oidc_provider_arn    = var.oidc_provider_arn
  oidc_subject         = var.oidc_subject
}

# Outputs
output "s3_bucket_name" {
  description = "Name of the S3 bucket"
  value       = module.s3.bucket_name
}

output "s3_bucket_arn" {
  description = "ARN of the S3 bucket"
  value       = module.s3.bucket_arn
}

output "rds_endpoint" {
  description = "RDS instance endpoint"
  value       = module.rds.endpoint
  sensitive   = true
}

output "rds_port" {
  description = "RDS instance port"
  value       = module.rds.port
}

output "iam_role_arn" {
  description = "ARN of the IAM role"
  value       = module.iam.role_arn
}

output "iam_role_name" {
  description = "Name of the IAM role"
  value       = module.iam.role_name
}

output "service_account_access_key_id" {
  description = "Access key ID for programmatic access (dev only)"
  value       = var.environment == "dev" ? module.iam.access_key_id : null
  sensitive   = true
}

output "service_account_secret_access_key" {
  description = "Secret access key for programmatic access (dev only)"
  value       = var.environment == "dev" ? module.iam.secret_access_key : null
  sensitive   = true
}
```

### `variables.tf`

```hcl
variable "aws_region" {
  description = "AWS region"
  type        = string
  default     = "us-east-1"
}

variable "environment" {
  description = "Environment name (dev, prod)"
  type        = string
  validation {
    condition     = contains(["dev", "prod"], var.environment)
    error_message = "Environment must be 'dev' or 'prod'."
  }
}

variable "project_name" {
  description = "Project name for resource naming"
  type        = string
}

# S3 Variables
variable "s3_retention_days" {
  description = "Number of days to retain old object versions"
  type        = number
  default     = 30
}

variable "replication_region" {
  description = "Region for S3 replication (prod only)"
  type        = string
  default     = "us-west-2"
}

variable "replication_bucket_arn" {
  description = "ARN of the replication bucket (prod only)"
  type        = string
  default     = null
}

# RDS Variables
variable "rds_instance_class" {
  description = "RDS instance type"
  type        = string
}

variable "rds_engine_version" {
  description = "PostgreSQL engine version"
  type        = string
  default     = "15.3"
}

variable "rds_allocated_storage" {
  description = "Allocated storage in GB"
  type        = number
  default     = 20
}

variable "rds_backup_retention" {
  description = "Backup retention period in days (minimum 7 for prod)"
  type        = number
  default     = 7
  validation {
    condition     = var.rds_backup_retention >= 7
    error_message = "Backup retention must be at least 7 days."
  }
}

variable "db_name" {
  description = "Initial database name"
  type        = string
  default     = "appdb"
}

variable "db_username" {
  description = "Master username"
  type        = string
  default     = "postgres"
  sensitive   = true
}

variable "db_password" {
  description = "Master password (use AWS Secrets Manager in production)"
  type        = string
  sensitive   = true
}

variable "db_subnet_group_name" {
  description = "DB subnet group name"
  type        = string
}

variable "db_security_group_ids" {
  description = "Security group IDs for RDS"
  type        = list(string)
}

# KMS Variables
variable "kms_key_arn" {
  description = "KMS key ARN for encryption (leave empty to use AWS managed key)"
  type        = string
  default     = null
}

# IAM Variables
variable "oidc_provider_arn" {
  description = "OIDC provider ARN for IRSA (prod only)"
  type        = string
  default     = null
}

variable "oidc_subject" {
  description = "OIDC subject for IRSA trust relationship (prod only)"
  type        = string
  default     = null
}
```

