## IAM Module

### `modules/iam/main.tf`

```hcl
# Service account role
resource "aws_iam_role" "service_account" {
  name               = var.service_account_name
  assume_role_policy = var.enable_oidc_trust ? data.aws_iam_policy_document.oidc_trust[0].json : data.aws_iam_policy_document.assume_role.json

  tags = {
    Name = var.service_account_name
  }
}

data "aws_iam_policy_document" "assume_role" {
  statement {
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
    actions = ["sts:AssumeRole"]
  }
}

data "aws_iam_policy_document" "oidc_trust" {
  count = var.enable_oidc_trust ? 1 : 0

  statement {
    effect = "Allow"
    principals {
      type        = "Federated"
      identifiers = [var.oidc_provider_arn]
    }
    actions = ["sts:AssumeRoleWithWebIdentity"]
    condition {
      test     = "StringEquals"
      variable = "${replace(var.oidc_provider_arn, "/^(.*provider/)/", "")}:sub"
      values   = [var.oidc_subject]
    }
    condition {
      test     = "StringEquals"
      variable = "${replace(var.oidc_provider_arn, "/^(.*provider/)/", "")}:aud"
      values   = ["sts.amazonaws.com"]
    }
  }
}

# S3 bucket policy
data "aws_iam_policy_document" "s3_access" {
  statement {
    sid    = "S3BucketAccess"
    effect = "Allow"
    actions = [
      "s3:ListBucket",
      "s3:GetBucketVersioning"
    ]
    resources = [var.s3_bucket_arn]
  }

  statement {
    sid    = "S3ObjectAccess"
    effect = "Allow"
    actions = [
      "s3:GetObject",
      "s3:PutObject",
      "s3:DeleteObject"
    ]
    resources = ["${var.s3_bucket_arn}/*"]
  }
}

resource "aws_iam_role_policy" "s3_access" {
  name   = "${var.service_account_name}-s3"
  role   = aws_iam_role.service_account.id
  policy = data.aws_iam_policy_document.s3_access.json
}

# RDS database access (dev: programmatic; prod: IRSA)
data "aws_iam_policy_document" "rds_access" {
  statement {
    sid    = "RDSConnect"
    effect = "Allow"
    actions = [
      "rds-db:connect"
    ]
    resources = ["${var.rds_arn}:db-user:${var.rds_resource_id}/*"]
  }

  statement {
    sid    = "DescribeRDS"
    effect = "Allow"
    actions = [
      "rds:DescribeDBInstances"
    ]
    resources = [var.rds_arn]
  }
}

resource "aws_iam_role_policy" "rds_access" {
  name   = "${var.service_account_name}-rds"
  role   = aws_iam_role.service_account.id
  policy = data.aws_iam_policy_document.rds_access.json
}

# Programmatic access (dev only)
resource "aws_iam_user" "service_account" {
  count = var.environment == "dev" ? 1 : 0
  name  = var.service_account_name

  tags = {
    Name = var.service_account_name
  }
}

resource "aws_iam_user_policy_attachment" "s3_access" {
  count      = var.environment == "dev" ? 1 : 0
  user       = aws_iam_user.service_account[0].name
  policy_arn = aws_iam_role_policy.s3_access.arn
}

resource "aws_iam_access_key" "service_account" {
  count = var.environment == "dev" ? 1 : 0
  user  = aws_iam_user.service_account[0].name
}
```

